using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
// Finite guard against moving the recovery flag creating a legacy migration self-lock.
public static class R1Migration {
 static string root;static CombatSession s;static bool done;static double deadline;
 [Serializable]class Row{public int version;public bool read,migrated,gateReleased,failureHeld,retryRecovered;public string error;}
 [Serializable]class Report{public string layer="Controlled Editor migration fixtures, not native";public Row[] rows;}
 public static void Run(){root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);deadline=EditorApplication.timeSinceStartup+240;EditorSceneManager.OpenScene("Assets/CombatPrototype/ForestRuins.unity");EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("migration deadline");if(done||!EditorApplication.isPlaying||Time.unscaledTime<.6f)return;s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s==null)return;done=true;var rows=new System.Collections.Generic.List<Row>();for(int v=1;v<=8;v++){
 string dir=root+"/v"+v;if(!s.Saves.InitializeFromEntry(dir,dir+"-legacy",true,SaveCatalog.Fingerprint(dir)))throw new Exception("isolated new");s.Saves.enabled=false;s.Saves.autoSaveInterval=3600;AdventureRandom.SetNextSeedForValidation(418);if(!s.Flow.Depart(AdventureMode.ForestExploration))throw new Exception("depart");foreach(var e in s.enemies){e.enabled=false;var b=e.GetComponent<ForestBossBrain>();if(b!=null)b.enabled=false;}s.Flow.OpenAbandon();s.Flow.ConfirmAbandon();string path=s.Saves.SavePath;s.Saves.WriteValidationHook=p=>{if(p=="after-publish"){File.Move(path,path+".held");throw new IOException("R1_MIGRATION_UNCERTAIN");}};s.Flow.CommitSettlement();s.Saves.WriteValidationHook=null;if(!s.Flow.SettlementNeedsRead)throw new Exception("initial read gate");
 string fixture=Path.GetDirectoryName(root)+"/Prepare/fixtures/v"+v+(v>=7?"-camp":"")+".json";byte[] original=File.ReadAllBytes(fixture);File.WriteAllBytes(path,original);if(File.Exists(s.Saves.BackupPath))File.Move(s.Saves.BackupPath,s.Saves.BackupPath+".held");
 // One failed migration publication must retain the read gate, then the same command retries.
 s.Saves.WriteValidationHook=p=>{if(p=="before-publish")throw new IOException("R1_MIGRATION_WRITE_FAILURE");};bool first=Primary();s.Saves.WriteValidationHook=null;bool held=!first&&s.Flow.SettlementNeedsRead&&!s.Saves.CanCommitWarehouse&&File.ReadAllBytes(path).SequenceEqual(original);bool read=Primary();var disk=CombatSaveSystem.InspectReadOnly(path);rows.Add(new Row{version=v,read=read,migrated=disk.sourceVersion==9,gateReleased=!s.Flow.SettlementNeedsRead&&s.Saves.CanCommitWarehouse,failureHeld=held,retryRecovered=read,error=s.Flow.Error});}
 File.WriteAllText(root+"/migration.json",JsonUtility.ToJson(new Report{rows=rows.ToArray()},true));Finish(rows.All(r=>r.read&&r.migrated&&r.gateReleased&&r.failureHeld&&r.retryRecovered)?0:1);
 }catch(Exception e){File.WriteAllText(root+"/migration-exception.txt",e.ToString());Finish(2);}}
 static bool Primary(){var method=typeof(AdventureFlow).GetMethod("ExecuteSettlementPrimaryAction");return method==null?s.Saves.LoadProgress(false):(bool)method.Invoke(s.Flow,null);}
 static void Finish(int code){if(s!=null){s.Saves.WriteValidationHook=null;s.Saves.SuspendEntry();}EditorApplication.update-=Tick;EditorApplication.Exit(code);}
}
